// Admissions (default: all live ones; admissions desk queue)  (permissions: ipd.admission.view)
export const listAdmissions = () =>
  api("GET", `/admissions`, undefined);   // api(): see get_guide('envelope-and-errors')

// Admission with bed, discharge stage and bill  (permissions: ipd.admission.view)
export const getAdmission = (admission_id) =>
  api("GET", `/admissions/${admission_id}`, undefined);   // api(): see get_guide('envelope-and-errors')

// Vitals grid, nursing notes, schedule & next due time  (permissions: ipd.flowsheet.view)
export const flowsheet = (admission_id) =>
  api("GET", `/admissions/${admission_id}/flowsheet`, undefined);   // api(): see get_guide('envelope-and-errors')

// Medication Administration Record (checklist)  (permissions: ipd.mar.view)
export const mar = (admission_id) =>
  api("GET", `/admissions/${admission_id}/mar`, undefined);   // api(): see get_guide('envelope-and-errors')

// Doctor: Discharge (Clinical Discharge stage)  (permissions: ipd.discharge.initiate)
export const discharge = (admission_id, body) =>
  api("POST", `/admissions/${admission_id}/discharge`, body);   // api(): see get_guide('envelope-and-errors')

// Which clearance stage the discharge is blocked on  (permissions: ipd.admission.view, ipd.discharge.clear_pharmacy, ipd.discharge.clear_nursing, ipd.discharge.clear_billing, ipd.discharge.clear_cleaning)
export const dischargeStatus = (admission_id) =>
  api("GET", `/admissions/${admission_id}/discharge-status`, undefined);   // api(): see get_guide('envelope-and-errors')

// Record the reason for admission and the provisional diagnosis (Code Red)  (permissions: ipd.admission.request, ipd.discharge.initiate)
export const admissionDetails = (admission_id, body) =>
  api("POST", `/admissions/${admission_id}/admission-details`, body);   // api(): see get_guide('envelope-and-errors')

// List patient documents  (permissions: patient.document.view)
export const listDocumentsPatients = (patient_id) =>
  api("GET", `/patients/${patient_id}/documents`, undefined);   // api(): see get_guide('envelope-and-errors')

// Download a patient document  (permissions: patient.document.view)
export const downloadDocumentPatientDocuments = (document_id) =>
  api("GET", `/patient-documents/${document_id}/download`, undefined);   // api(): see get_guide('envelope-and-errors')
